    try { state.writer?.abort?.(); } catch {}
    try { state.writer?.releaseLock?.(); } catch {}
    try { state.reader?.cancel?.(); } catch {}
    try { state.reader?.releaseLock?.(); } catch {}
    try { state.socket?.close?.(); } catch {}
